## Signatures used in the examples

These are inferred from the examples below, since the page doesn't give formal type declarations:

- `ctx.loop(name, async (loopCtx) => {...})`
- `loopCtx.queue.next(name)` and `loopCtx.queue.nextBatch(name, { timeout })`
- `loopCtx.sleep(name, ms)` and `loopCtx.sleepUntil(name, timestamp)`
- `loopCtx.join(name, { branchName: { run: async (branchCtx) => ... } })`
- `ctx.race(name, [{ name, run: async (branchCtx) => ... }])`, which returns the winner's name and value
- `branchCtx.step`, `branchCtx.sleep`, and `branchCtx.queue.next` inside branches

## Timers (queue + `sleepUntil`)

```ts
import { queue, setup, workflow } from "@rivet-dev/workflows";

type Reminder = {
	text: string;
	at: number;
};
export const reminderActor = workflow({
	state: {
		fired: [] as string[],
	},
	queues: {
		reminders: queue<Reminder>(),
	},
	run: async (ctx) => {
		await ctx.loop("reminder-loop", async (loopCtx) => {
			const message = await loopCtx.queue.next("wait-reminder");
			const runAt = Math.max(Date.now(), message.body.at);
			await loopCtx.sleepUntil("wait-until-reminder", runAt);
			await loopCtx.step("record-reminder", async (step) => {
				step.state.fired.push(message.body.text);
			});
		});
	},
	actions: {
		getState: (c) => c.state,
	},
});
export const registry = setup({ use: { reminderActor } });
```

## Join (parallel branches)

```ts
import { queue, setup, workflow } from "@rivet-dev/workflows";
export const dashboardActor = workflow({
	state: {
		summary: null as null | {
			users: number;
			orders: number;
			revenue: number;
		},
	},
	queues: {
		refresh: queue<Record<string, never>>(),
	},
	run: async (ctx) => {
		await ctx.loop("dashboard-loop", async (loopCtx) => {
			await loopCtx.queue.next("wait-refresh");
			const summary = await loopCtx.join("fetch-summary", {
				users: {
					run: async (branchCtx) => {
						return await branchCtx.step("fetch-users", (_branchCtx) =>
							fetchCount("/users"),
						);
					},
				},
				orders: {
					run: async (branchCtx) => {
						return await branchCtx.step("fetch-orders", (_branchCtx) =>
							fetchCount("/orders"),
						);
					},
				},
				revenue: {
					run: async (branchCtx) => {
						return await branchCtx.step("fetch-revenue", (_branchCtx) =>
							fetchCount("/revenue"),
						);
					},
				},
			});
			await loopCtx.step("save-summary", async (step) => {
				step.state.summary = summary;
			});
		});
	},
	actions: {
		getState: (c) => c.state,
	},
});
async function fetchCount(path: string): Promise<number> {
	const res = await fetch(`https://api.example.com${path}`);
	if (!res.ok) throw new Error(`fetch ${path} failed: ${res.status}`);
	return (
		(await res.json()) as {
			count: number;
		}
	).count;
}
export const registry = setup({ use: { dashboardActor } });
```

## Race (first winner)

```ts
import { queue, setup, workflow } from "@rivet-dev/workflows";
export const auctionActor = workflow({
	state: { result: null as "sold" | "expired" | null },
	queues: {
		bids: queue<{
			amount: number;
		}>(),
	},
	run: async (ctx) => {
		await ctx.step("list-item", (_ctx) => listItem("item-123"));
		const { winner } = await ctx.race("bid-or-expire", [
			{
				name: "bid",
				run: async (branchCtx) => {
					const bid = await branchCtx.queue.next("wait-bid");
					return bid.body.amount;
				},
			},
			{
				name: "expire",
				run: async (branchCtx) => {
					await branchCtx.sleep("auction-timeout", 24 * 60 * 60 * 1000);
					return 0;
				},
			},
		]);
		await ctx.step("finalize", async (step) => {
			await finalizeAuction("item-123", winner);
			step.state.result = winner === "bid" ? "sold" : "expired";
		});
	},
	actions: {
		getState: (c) => c.state,
	},
});
async function listItem(itemId: string): Promise<void> {
	await fetch(`https://api.example.com/auctions/${itemId}`, {
		method: "POST",
	});
}
async function finalizeAuction(itemId: string, outcome: string): Promise<void> {
	await fetch(`https://api.example.com/auctions/${itemId}/finalize`, {
		method: "POST",
		body: JSON.stringify({ outcome }),
	});
}
export const registry = setup({ use: { auctionActor } });
```

## Fan-out / fan-in (join with batch loop)

```ts
import { setup, workflow } from "@rivet-dev/workflows";
export const fanInOutActor = workflow({
	state: {
		total: 0,
	},
	run: async (ctx) => {
		await ctx.loop("join-loop", async (loopCtx) => {
			const [message] = await loopCtx.queue.nextBatch("wait-refresh", {
				timeout: 30000,
			});
			if (!message) return;
			const joined = await loopCtx.join("parallel-work", {
				users: {
					run: async (branchCtx) =>
						await branchCtx.step("fetch-users", (_branchCtx) =>
							fetchCount("/users"),
						),
				},
				orders: {
					run: async (branchCtx) =>
						await branchCtx.step("fetch-orders", (_branchCtx) =>
							fetchCount("/orders"),
						),
				},
				invoices: {
					run: async (branchCtx) =>
						await branchCtx.step("fetch-invoices", (_branchCtx) =>
							fetchCount("/invoices"),
						),
				},
			});
			await loopCtx.step("merge-results", async (step) => {
				step.state.total = joined.users + joined.orders + joined.invoices;
			});
		});
	},
	actions: {
		getState: (c) => c.state,
	},
});
async function fetchCount(path: string): Promise<number> {
	const res = await fetch(`https://api.example.com${path}`);
	if (!res.ok) throw new Error(`fetch ${path} failed: ${res.status}`);
	return (
		(await res.json()) as {
			count: number;
		}
	).count;
}
export const registry = setup({ use: { fanInOutActor } });
```

## Poll + backoff (loop + sleep)

```ts
import { setup, workflow } from "@rivet-dev/workflows";

async function pollExternal(attempt: number): Promise<boolean> {
	return attempt % 3 === 0;
}
export const pollBackoffActor = workflow({
	state: {
		attempts: 0,
		backoffMs: 100,
		status: "unknown" as "unknown" | "healthy" | "retrying",
	},
	run: async (ctx) => {
		await ctx.loop("poll-loop", async (loopCtx) => {
			const success = await loopCtx.step("poll-target", async (step) => {
				step.state.attempts += 1;
				return pollExternal(step.state.attempts);
			});
			if (success) {
				await loopCtx.step("reset-backoff", async (step) => {
					step.state.status = "healthy";
					step.state.backoffMs = 100;
				});
				await loopCtx.sleep("healthy-interval", 1000);
				return;
			}
			const retryDelay = await loopCtx.step("grow-backoff", async (ctx) => {
				ctx.state.status = "retrying";
				ctx.state.backoffMs = Math.min(ctx.state.backoffMs * 2, 5000);
				return ctx.state.backoffMs;
			});
			await loopCtx.sleep("retry-delay", retryDelay);
		});
	},
	actions: {
		getState: (c) => c.state,
	},
});
export const registry = setup({ use: { pollBackoffActor } });
```

## Timeout + fallback (race + loop)

```ts
import {
	actor,
	setup,
	type WorkflowStepContextOf,
	workflow,
} from "@rivet-dev/workflows";
export const primaryServiceActor = actor({
	actions: {
		fetchValue: async () => {
			await new Promise((resolve) => setTimeout(resolve, 500));
			return "primary";
		},
	},
});
export const fallbackServiceActor = actor({
	actions: {
		fetchValue: async () => "fallback",
	},
});
export const timeoutFallbackActor = workflow({
	state: {
		lastSource: "none" as "none" | "primary" | "fallback",
		lastValue: "",
	},
	run: async (ctx) => {
		await ctx.loop("timeout-loop", async (loopCtx) => {
			await loopCtx.queue.nextBatch("wait-request", {
				timeout: 30000,
			});
			const winner = await loopCtx.race("primary-vs-timeout", [
				{
					name: "primary",
					run: async (raceCtx) =>
						await raceCtx.step("call-primary", async (step) =>
							callPrimaryValue(step),
						),
				},
				{
					name: "timeout",
					run: async (raceCtx) => {
						await raceCtx.sleep("primary-timeout", 200);
						return "timeout";
					},
				},
			]);
			let value = winner.value as string;
			let source: "primary" | "fallback" = "primary";
			if (winner.winner === "timeout") {
				value = (await loopCtx.step("fallback-call", async (step) =>
					callFallbackValue(step),
				)) as string;
				source = "fallback";
			}
			await loopCtx.step("record-choice", async (step) => {
