			Object.assign(step.state, r);
			return r;
		});
		const mounts: Mounts = { repo: req.repo, outbox };

		// One micro-VM per run: the host repo mounted read-only at /src, the
		// run's outbox (a bare repo on the host) writable at /out, and a clone in
		// /work/repo. Idempotent, so a replay reattaches and skips work done.
		await ctx.step({
			name: "provision-box",
			...AGENT_STEP,
			run: async () => {
				const { box: vm, sdk } = agentFor(box, mounts);
				await sh(vm, [
					`[ -d ${WORK} ] || git clone --quiet --no-checkout ${SRC} ${WORK}`,
					`git -C ${WORK} checkout --quiet --detach ${baseSha}`,
					...(implementing
						? [`[ -d ${IMPL} ] || git -C ${WORK} worktree add --quiet -b ${branch(req.key)} ${IMPL} ${baseSha}`]
						: []),
				].join(" && "));
				await sdk;
			},
		});

		let headSha = resolved.headSha;
		if (implementing) {
			await ctx.step("implementing", async (step) => {
				step.state.status = "implementing";
			});
			const implementation = await ctx.step({
				name: "implement",
				...IMPLEMENT_STEP,
				run: async () =>
					implement({
						sdk: await agentFor(box, mounts).sdk,
						sessionId: sessionId(req.key, "impl"),
						cwd: IMPL,
						model: "sonnet",
						prompt: implementPrompt(req.task),
					}),
			});

			// The workflow commits, not the agent: the SHA is recorded in step
			// history, so reviewers and every replay see exactly this commit.
			headSha = await ctx.step("commit", async () => {
				const { box: vm } = agentFor(box, mounts);
				const subject = `feat: ${req.task.split("\n")[0].slice(0, 60)}`;
				await sh(vm, `cd ${IMPL} && git add -A && (git diff --cached --quiet || git commit --quiet -F -) <<'MSG'
${subject}

${implementation.summary.slice(0, 4000)}

Rivet-Run: ${req.key}
MSG`);
				const sha = (await sh(vm, `git -C ${IMPL} rev-parse HEAD`)).trim();
				if (sha === baseSha) throw new Error("implementer made no changes");
				return sha;
			});

			// Export: the only write to the host, by the workflow, to the run's outbox.
			const exportRef = await ctx.step("export", async (step) => {
				const { box: vm } = agentFor(box, mounts);
				await sh(vm, `git -C ${IMPL} push --quiet --force ${OUT} ${headSha}:refs/heads/${branch(req.key)}`);
				step.state.implementation = implementation;
				step.state.headSha = headSha;
				return `${outbox} ${branch(req.key)}`;
			});
			await ctx.step("record-export", async (step) => {
				step.state.exportRef = exportRef;
			});
		}

		const change = `the diff \`git diff ${baseSha}...${headSha}\` in this repository`;
		await ctx.step("prepare-review", async (step) => {
			const { box: vm } = agentFor(box, mounts);
			await sh(vm, REVIEW_FACETS.map(
				(f) => `[ -d ${worktree(f.id)} ] || git -C ${WORK} worktree add --quiet --detach ${worktree(f.id)} ${headSha}`,
			).join(" && "));
			step.state.diffStat = (await sh(vm, `git -C ${WORK} diff --stat ${baseSha}...${headSha}`)).trim();
			step.state.status = "reviewing";
		});

		// Fan out: one durable branch per facet, each a Claude Code session in
		// its own worktree at the change's head.
		const branches = Object.fromEntries(
			REVIEW_FACETS.map((facet) => [
				facet.id,
				{
					run: async (b: { tryStep: typeof ctx.tryStep }) => {
						const r = await b.tryStep({
							name: `review-${facet.id}`,
							...AGENT_STEP,
							run: async () =>
								review({
									sdk: await agentFor(box, mounts).sdk,
									sessionId: sessionId(req.key, facet.id),
									cwd: worktree(facet.id),
									model: modelFor(facet),
									prompt: facetPrompt(facet, change, req.task),
								}),
						});
						return (r.ok ? { ok: true, result: r.value } : { ok: false, error: String(r.failure.error?.message ?? r.failure.kind) }) as FacetOutcome;
					},
				},
			]),
		);
		const outcomes = (await ctx.join("review-facets", branches as any)) as Record<string, FacetOutcome>;

		await ctx.step("record-facets", async (step) => {
			step.state.facets = outcomes;
			step.state.status = "reranking";
		});

		// Fan in: rerank across facets, in a worktree at the change's head.
		const sections = REVIEW_FACETS.map((f) => {
			const o = outcomes[f.id];
			const body = o.ok ? JSON.stringify(o.result.findings, null, 2) : `(reviewer failed: ${o.error})`;
			return `## ${f.name} findings\n${body}\n`;
		}).join("\n");
		const rerank = await ctx.step({
			name: "rerank",
			...AGENT_STEP,
			run: async () =>
				review({
					sdk: await agentFor(box, mounts).sdk,
					sessionId: sessionId(req.key, "reranker"),
					cwd: worktree(REVIEW_FACETS[0].id),
					model: "sonnet",
					prompt: rerankerPrompt(sections, change, req.task, REVIEW_FACETS.length),
				}),
		});

		await ctx.step("finish", async (step) => {
			step.state.rerank = rerank;
			step.state.kept = rerank.findings;
			step.state.status = "complete";
			step.state.finishedAt = Date.now();
		});
		await ctx.step("close-box", () => closeBox(box, mounts));
	},
	actions: {
		getState: (c) => c.state,
		/** Queue a message for one agent ("impl", a facet, or "reranker"); delivered when its current turn ends. */
		steer: (c, who: string, text: string) => {
			if (!c.state.request) throw new Error("run has not started");
			steer(sessionId(c.state.request.key, who), text);
			return { queuedFor: sessionId(c.state.request.key, who) };
		},
	},
});

export const registry = setup({ use: { prReview } });

