const fs=require("fs");const p="src/registry.ts";let s=fs.readFileSync(p,"utf8");
const startMarker="		const implementing = req.mode === "implement";
";
const endMarker="		await ctx.step("close-box", () => closeBox(box, mounts));
";
const a=s.indexOf(startMarker)+startMarker.length, b=s.indexOf(endMarker)+endMarker.length;
